using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Windows.Forms;

namespace PolarisStandalone
{
    // Approved North Star Orbit assets embedded so installation needs no sidecar files.
    internal sealed class PolarisMark : Control
    {
        internal static string ImageDataUrl { get { return "data:image/png;base64," + PngData; } }
        private static readonly Bitmap Artwork = LoadArtwork();
        private static readonly Icon AppIcon = LoadIcon();
        internal PolarisMark()
        {
            SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer, true);
            AccessibleName = "Project Polaris North Star Orbit logo";
            AccessibleRole = AccessibleRole.Graphic;
            TabStop = false;
        }
        private static Bitmap LoadArtwork()
        {
            using (var stream = new MemoryStream(Convert.FromBase64String(PngData)))
            using (var image = Image.FromStream(stream)) return new Bitmap(image);
        }
        private static Icon LoadIcon()
        {
            using (var stream = new MemoryStream(Convert.FromBase64String(IconData)))
            using (var icon = new Icon(stream, 32, 32)) return (Icon)icon.Clone();
        }
        internal static void DrawMark(Graphics g, RectangleF bounds)
        {
            float size = Math.Min(bounds.Width, bounds.Height);
            if (size <= 0) return;
            var state = g.Save();
            try
            {
                g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = PixelOffsetMode.HighQuality;
                g.DrawImage(Artwork, new RectangleF(bounds.X + (bounds.Width-size)/2,
                    bounds.Y + (bounds.Height-size)/2, size, size));
            }
            finally { g.Restore(state); }
        }
        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            DrawMark(e.Graphics, ClientRectangle);
        }
        internal static Icon WindowIcon() { return (Icon)AppIcon.Clone(); }
        private const string PngData = "";
        private const string IconData = "";
    }
}

